        if (minDegree < 2) {
            throw new IllegalArgumentException("Minimum degree must be at least 2");
        }
        this.minDegree = minDegree;
        this.root = null;
    }

    public void traverse() {
        if (root != null) {
            root.traverse();
        }
    }

